package com.example.todo.entity; import jakarta.persistence.*; import lombok.*; @Entity @Table(name="todos") @Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder public class Todo { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false,length=200) private String title; @Column(length=2000) private String description; @Column(nullable=false) private boolean completed; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="user_id",nullable=false) private User user; }
